/**
 * Packs an array of entities into an ArrayBuffer.
 *
 * @param {Array<Object>} entities An array of entities, where each entity has 'id' (4 bits) and 'size' (3 bits) properties.
 * @returns {ArrayBuffer} An ArrayBuffer containing the packed entities.
 * @throws {Error} If any entity has an invalid 'id' or 'size' value.
 */
function packEntities(entities) {
  const totalBits = entities.length * 7; // 4 bits for id + 3 bits for size = 7 bits per entity
  const buffer = new ArrayBuffer(Math.ceil(totalBits / 8));
  const dataView = new DataView(buffer);
  let bitOffset = 0;

  for (const entity of entities) {
    const id = entity.id;
    const size = entity.size;

    if (id < 0 || id > 15) {
      throw new Error("Invalid entity id: " + id + ". Must be between 0 and 15.");
    }
    if (size < 0 || size > 7) {
      throw new Error("Invalid entity size: " + size + ". Must be between 0 and 7.");
    }

    // Pack id (4 bits)
    let idByteIndex = Math.floor(bitOffset / 8);
    let idBitOffset = bitOffset % 8;
    dataView.setUint8(idByteIndex, (dataView.getUint8(idByteIndex) & 0x0F) | (id << (8 - idBitOffset)));
    bitOffset += 4;

    // Pack size (3 bits)
    let sizeByteIndex = Math.floor(bitOffset / 8);
    let sizeBitOffset = bitOffset % 8;
    dataView.setUint8(sizeByteIndex, (dataView.getUint8(sizeByteIndex) & 0x07) | (size << (8 - sizeBitOffset)));
    bitOffset += 3;
  }

  return buffer;
}

/**
 * Unpacks an array of entities from an ArrayBuffer.
 *
 * @param {ArrayBuffer} buffer The ArrayBuffer containing the packed entities.
 * @returns {Array<Object>} An array of entities, where each entity has 'id' (4 bits) and 'size' (3 bits) properties.
 */
function unpackEntities(buffer) {
  const dataView = new DataView(buffer);
  const entities = [];
  let bitOffset = 0;

  while (bitOffset < buffer.byteLength * 8) {
    const byteIndex = Math.floor(bitOffset / 8);
    const bitOffsetInByte = bitOffset % 8;

    // Extract id (4 bits)
    const id = (dataView.getUint8(byteIndex) >> (8 - bitOffsetInByte)) & 0x0F;

    // Extract size (3 bits)
    const size = (dataView.getUint8(byteIndex) >> (8 - bitOffsetInByte - 4)) & 0x07;

    entities.push({ id, size });
    bitOffset += 7;
  }

  return entities;
}
